const item = $input.item.json;
const cfg = item.cfg || {};
const b = cfg.broll || {};
const rawTopic = item['Topic'] || '';
const fullId = item.id || '';
const shortId = fullId ? fullId.substring(0, 7) : 'norec';
let slug = rawTopic.toLowerCase().replace(/[^\w\s-]/g, '').replace(/\s+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '');
if (slug.length > 40) { slug = slug.substring(0, 40); const cut = slug.lastIndexOf('-'); if (cut > 15) slug = slug.substring(0, cut); }
slug = slug.replace(/^-|-$/g, '') || 'broll';
const genDate = $now.setZone(cfg.timezone || 'Asia/Manila').toFormat('yyyy-MM-dd');
const folderName = genDate + '_' + slug + '_' + shortId;
const ratio = item['Ratio'] || '';
const ratioText = ratio === 'Portrait' ? 'vertical 9:16 portrait format' : 'horizontal 16:9 landscape format';
const aspectRatio = ratio === 'Portrait' ? '9:16' : '16:9';

const sep = b.notes_separator || '==============================';
const NOTES_TAG = b.stage_tag || 'B-ROLL (Manus skill)';
const REF_TAG = b.ref_tag || 'B-ROLL CLIP INDEX (Manus skill)';
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const blockRe = (tag) => new RegExp('\\n*' + esc(sep) + '\\n' + esc(tag) + '[\\s\\S]*?(?=(\\n' + esc(sep) + '\\n)|$)', 'g');

const notesBase = (item['Reel_Notes'] || '').replace(blockRe(NOTES_TAG), '').trim();
const refBase = (item['BRoll_Reference'] || '').replace(blockRe(REF_TAG), '').trim();

return { json: {
  cfg: cfg,
  record_id: fullId,
  topic: rawTopic,
  folder_name: folderName,
  gen_date: genDate,
  short_id: shortId,
  script: item['Script'] || '',
  category: item['Category'] || 'General',
  broll_generated: item['BRoll_Generated'] || '',
  broll_reference: refBase,
  sep: sep,
  stage_tag: NOTES_TAG,
  ref_tag: REF_TAG,
  notes_base: notesBase,
  ratio: ratio,
  ratio_text: ratioText,
  aspect_ratio: aspectRatio
} };

const folderResponse = $input.item.json;
const ctx = $('3. Build Scenes from Brief').item.json;
const folderId = folderResponse.id || '';
const folderLink = folderId ? 'https://drive.google.com/drive/folders/' + folderId : '';
return { json: { ...ctx, folder_id: folderId, folder_link: folderLink, folder_ok: !!folderId } };

const d = $input.item.json;
const cfg = d.cfg || {};
const b = cfg.broll || {};
const BRAND = cfg.brand_name || cfg.client_name || 'the brand';
const folderId = d.folder_id || '';
const folderUrl = d.folder_link || '';
const aspect = d.aspect_ratio || '16:9';
const scenePayload = d.scenes.map(s => ({
  id: s.id,
  file_name: s.file_name,
  scene_direction: s.scene_direction,
  style_reference: s.style_reference,
  duration_seconds: s.duration_seconds,
  timing_start: s.timing_start,
  timing_end: s.timing_end,
  chain_from_previous: s.chain_from_previous === true
}));
const chained = scenePayload.filter(s => s.chain_from_previous).map(s => s.id);
const M = [];
M.push('Render the complete B-roll clip set for one ' + BRAND + ' reel, then upload every clip to Google Drive. Follow every instruction below exactly.');
M.push('');
M.push('NON-INTERACTIVE - READ THIS FIRST: This task was dispatched automatically by n8n. There is no human in this session and no one will answer a question. Do NOT ask clarifying questions. Do NOT wait for confirmation. Do NOT present options and pause. Skip the skill clarifying-questions step entirely. Duration, aspect ratio and timing are fixed per scene in the payload below. Everything else - narrative role, visual style, metaphor, palette, mood - is yours to decide from your own skill references. Proceed straight to generation. If something is genuinely missing, note it in your task output and continue - never stall.');
M.push('');
M.push('GENERATOR: Use the standard Manus generation tools - generate_image for keyframes and generate_video for clips. Do NOT use Higgsfield for this task. Higgsfield is out of scope for automated b-roll and its credits are reserved for manual, highly customised work.');
M.push('');
M.push('BATCH: This is a full clip set, not a single scene. Render ALL ' + d.scene_count + ' scenes below in one task. Do not stop after the first scene.');
M.push('');
M.push('ASPECT RATIO: ' + aspect + '. Every keyframe and every clip must be this aspect ratio. No letterboxing, no padding, no cropping after the fact.');
M.push('');
M.push('SCENES (from the approved production brief for this video):');
M.push(JSON.stringify(scenePayload, null, 2));
M.push('');
M.push('YOUR JOB - EVERYTHING CREATIVE. The payload gives you content and timing only. Your skill references are the SOLE authority on all of the following, and none of it is specified above:');
M.push('1. NARRATIVE ROLE. Read each scene_direction and assign it the best-fitting narrative role from your own scene-type table. Do not ask which role to use - decide it yourself from the direction and the position of the scene in the sequence.');
M.push('2. VISUAL STYLE. Decide abstract or realistic per scene according to your own style rules for the role you assigned.');
M.push('3. VISUAL METAPHOR. Select the metaphor from your scene-type templates that best fits the role and the direction. Do not default to the same metaphor across scenes.');
M.push('4. BRAND. Palette, colour values, lighting and visual treatment all come from your brand-assets reference. The payload deliberately omits them.');
M.push('5. PROMPT STRUCTURE. Apply your documented video prompt structure and technical specs.');
M.push('');
M.push('scene_direction is what must actually happen in the clip and is specific to this script - honour it. style_reference is the stock-footage style note from the same brief, use it as a visual hint only. Render each scene for its duration_seconds value, not your default.');
M.push('');
M.push('KEYFRAMES AND MOTION (mandatory):');
M.push('1. Every scene is its own distinct shot unless it has chain_from_previous = true. ' + (chained.length ? 'Chained scenes in this set: ' + chained.join(', ') + '. Every other scene is unchained.' : 'No scene in this set is chained, so every scene is unchained.'));
M.push('2. For every unchained scene, call generate_image twice at aspect ratio ' + aspect + ' - a first keyframe and a last keyframe - both composed from the scene_direction of that same scene. Then call generate_video with keyframes.first and keyframes.last set and generate_audio false.');
M.push('3. The first and last keyframe of a scene show the same subject and setting, with the camera in a clearly different position or the subject in a clearly different state, so the clip moves across its whole length: push-in, pull-out, pan, orbit, tracking shot, or the subject carrying out the action in scene_direction. Never pair two unrelated images as first and last keyframe - that renders a held frame followed by a late morph.');
M.push('4. Never hold the first frame. Motion starts in the first second and continues to the last frame. A clip that stays near-static and then morphs into its end image near the end is a failed clip.');
M.push('5. Never reuse a keyframe, opening frame or closing frame from another scene as the first keyframe of an unchained scene. Every unchained scene opens on a frame that is visibly different from the opening frame of every other scene.');
M.push('6. Only for a scene with chain_from_previous = true: extract the final frame of the immediately preceding rendered clip with ffmpeg (last frame, full resolution, PNG), use it as keyframes.first, and generate the last keyframe fresh so the camera or subject keeps moving through the clip. Render a chained scene only after the scene before it has finished.');
M.push('');
M.push('PRE-SHIP QUALITY CHECK (mandatory - run it with ffmpeg on the rendered clips BEFORE uploading anything):');
M.push('1. CLIP COUNT: exactly ' + d.scene_count + ' clips exist, one per scene, none missing, none duplicated.');
M.push('2. ASPECT RATIO: every clip is ' + aspect + '.');
M.push('3. DURATION: every clip matches its duration_seconds within 1 second.');
M.push('4. DISTINCT OPENINGS: extract the first frame of every clip and compare it with the first frame of every other clip (ffmpeg ssim filter, both frames scaled to 320 px wide). An unchained clip whose first frame matches the first frame of another clip (SSIM 0.90 or higher) fails.');
M.push('5. MOTION: extract frames at 10, 25, 40, 55 and 70 percent of the clip duration and compare each frame with the next one (same SSIM method). A clip where every consecutive pair scores SSIM 0.97 or higher has barely moved and fails.');
M.push('6. CHAINED SEAMS: every chained clip opens on the closing frame of the previous clip with no visible jump, colour shift, or subject teleport.');
M.push('7. BRAND: colours and visual treatment match your brand-assets reference. No text overlays, no logos, no captions, no watermarks burned into any clip.');
M.push('8. AUDIO: every clip is silent. No generated audio, no music, no voiceover.');
M.push('9. INTEGRITY: no clip is corrupt, black, or truncated. Each plays start to finish.');
M.push('');
M.push('REGENERATE ONCE: a clip that fails any check is re-rendered one time only, with new first and last keyframes that follow the KEYFRAMES AND MOTION rules, and then checked again. If it still fails, keep the better of the two renders, upload it, and flag it in the clip index. Never re-render any clip more than once.');
M.push('');
M.push('UPLOAD (MANDATORY - required final step, do not skip it. Do not stop at a production brief):');
M.push('DESTINATION_FOLDER_ID: ' + folderId);
M.push('DESTINATION_FOLDER_URL: ' + folderUrl);
M.push('');
M.push('Export each clip as MP4 named exactly with its file_name value from the scene list above. After the quality check, upload ALL clips to the user Google Drive using rclone, targeting the EXISTING destination folder by its ID with the flag --drive-root-folder-id ' + folderId + ' so the MP4s land directly INSIDE that existing folder. The destination is a shared drive, so include shared-drive support. Run the upload EXACTLY ONCE; do not re-run or duplicate. Do NOT create a new folder. Do NOT use the folder ID as a new folder name. Do NOT rename the files. Do NOT leave the clips only in your task workspace. Do NOT upload any stills, keyframes, frame grabs, thumbnails, logs, or intermediate files to that folder - only the ' + d.scene_count + ' final MP4 clips.');
M.push('');
M.push('OUTPUT - CLIP INDEX: After uploading, list in your task output every file you placed in that folder, each with its file name, timing_start, the narrative role and metaphor you selected, chained yes or no, the highest opening-frame SSIM against any other clip (check 4), and the lowest consecutive-frame SSIM from check 5. Mark every clip that still failed after its one re-render as QA FAIL with the check it failed and the measured value. A production brief is not required.');
const msg = M.join('\n');
return { json: { ...d, manus_message: msg } };

const resp = $input.item.json || {};
const ctx = $('5. Build Manus Message').item.json;
const cfg = ctx.cfg || {};
const b = cfg.broll || {};
const rec = ctx.record_id || '(no id)';
const client = cfg.client_name || '(unknown client)';
const project = String(cfg.manus_project_id || b.manus_project_id || '').trim();
const fromOutputs = String(cfg.skill_name || '').trim();
const wanted = fromOutputs || String(b.skill_name || '').trim();
const source = fromOutputs ? 'client config (Skill_Name)' : 'client config (Config_JSON broll.skill_name)';
if (!project) { throw new Error('No Manus project ID configured for ' + client + '::broll on record ' + rec + '. Nothing submitted.'); }
if (!wanted) { throw new Error('No Manus skill configured for ' + client + '::broll on record ' + rec + '. Nothing submitted.'); }
if (resp.ok === false || !Array.isArray(resp.data)) { throw new Error('skill.list failed for Manus project ' + project + ' on record ' + rec + ': ' + JSON.stringify(resp).substring(0, 300) + '. Nothing submitted.'); }
const all = resp.data.filter(Boolean);
const norm = s => String(s || '').trim().toLowerCase();
const projectSkills = all.filter(s => s.owner_type === 'project');
const matches = projectSkills.filter(s => norm(s.name) === norm(wanted));
if (matches.length !== 1 || !matches[0].id) {
  const nonProject = all.filter(s => s.owner_type !== 'project' && norm(s.name) === norm(wanted)).map(s => (s.owner_type || 'unknown') + ' ' + s.id);
  let why;
  if (matches.length > 1) why = matches.length + ' project skills share this name (' + matches.map(s => s.id).join(', ') + ')';
  else if (nonProject.length) why = 'only non-project copies exist [' + nonProject.join(', ') + ']; personal, team, official and app skills are not allowed';
  else why = 'no project skill with this name';
  throw new Error('Skill ' + wanted + ' (' + source + ') not resolved for record ' + rec + ' in Manus project ' + project + ': ' + why + '. Project skills available: ' + (projectSkills.map(s => s.name).join(', ') || '(none)') + '. Nothing submitted.');
}
const hit = matches[0];
const body = {
  message: { content: [{ type: 'text', text: ctx.manus_message }], enable_skills: [hit.id], force_skills: [hit.id] },
  title: (ctx.topic || 'B-Roll') + ' - ' + ctx.record_id,
  project_id: project,
  hide_in_task_list: false,
  agent_profile: b.agent_profile || 'manus-1.6'
};
return { json: { ...ctx, manus_project_id: project, resolved_skill_id: hit.id, resolved_skill_name: hit.name || wanted, resolved_skill_owner_type: hit.owner_type, resolved_skill_source: source, skill_resolve_error: '', manus_body: JSON.stringify(body) } };

const r = $input.item.json || {};
const ctx = $('5c. Pick Skill').item.json;
const taskId = r.task_id || (r.data && r.data.task_id) || '';
if (!taskId || r.ok === false) { throw new Error('Manus task.create failed for record ' + (ctx.record_id || '(no id)') + ' with skill ' + ctx.resolved_skill_name + ' (' + ctx.resolved_skill_owner_type + ', ' + ctx.resolved_skill_id + '): no task_id returned. Response: ' + JSON.stringify(r).substring(0, 400)); }
const taskUrl = r.task_url || (r.data && r.data.task_url) || ('https://manus.im/app/' + taskId);
const driveQ = "'" + ctx.folder_id + "' in parents and trashed = false and mimeType contains 'video/'";
return { json: {
  ...ctx,
  manus_task_id: taskId,
  manus_task_url: taskUrl,
  manus_has_task: true,
  manus_error: '',
  drive_q: driveQ,
  poll_attempt: 0
} };

const resp = $input.item.json;
const ctx = $('6a. Restore Before Poll').item.json;
const b = (ctx.cfg || {}).broll || {};
const MAX_POLL_ATTEMPTS = b.max_poll_attempts || 24;
const files = (resp && Array.isArray(resp.files)) ? resp.files : [];
const found = files.length;
const expected = ctx.scene_count || 0;
const allIn = expected > 0 && found >= expected;
const timedOut = !allIn && ctx.poll_attempt >= MAX_POLL_ATTEMPTS;
return { json: {
  ...ctx,
  clips_found: found,
  clips_expected: expected,
  clip_names: files.map(f => f.name),
  all_clips_in: allIn,
  poll_timed_out: timedOut,
  max_poll_attempts: MAX_POLL_ATTEMPTS
} };

const fresh = $input.item.json || {};
const d = $('6c. Parse Clip Count').item.json;
const f = fresh.fields || fresh;
const refetchOk = !!(fresh && fresh.id);
const freshRef = (f && typeof f.BRoll_Reference === 'string') ? f.BRoll_Reference : (d.broll_reference || '');
const freshNotes = (f && typeof f.Reel_Notes === 'string') ? f.Reel_Notes : '';

const sep = d.sep;
const NOTES_TAG = d.stage_tag;
const REF_TAG = d.ref_tag;
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const blockRe = (tag) => new RegExp('\\n*' + esc(sep) + '\\n' + esc(tag) + '[\\s\\S]*?(?=(\\n' + esc(sep) + '\\n)|$)', 'g');
const stamp = new Date().toISOString().substring(0, 16).replace('T', ' ');

let triggered = '';
let runtime = 'unknown';
try {
  const raw = $('1z. Attach Config').first().json.started_at || '';
  triggered = raw ? raw.substring(0, 16).replace('T', ' ') : '';
  const s = Date.parse(raw);
  if (s) { const secs = Math.max(0, Math.round((Date.now() - s) / 1000)); runtime = Math.floor(secs / 60) + 'm ' + (secs % 60) + 's'; }
} catch (e) {}

const names = d.clip_names || [];

// Full clip index for BRoll_Reference - one entry per clip with the edit timestamp.
const rows = d.scenes.map(s => {
  const landed = names.indexOf(s.file_name) !== -1;
  const dir = String(s.scene_direction || '').substring(0, 160);
  return 'INSERT AT ' + s.timing_start + ' - ' + s.timing_end + '  (' + s.duration_seconds + 's)\n  Clip: ' + s.file_name + (landed ? '' : '   <-- MISSING FROM DRIVE') + '\n  Chained from previous: ' + (s.chain_from_previous ? 'yes' : 'no') + '\n  Direction: ' + dir;
}).join('\n\n');

// Compact edit timeline for Reel_Notes so the editor sees placement without opening the reference field.
const timeline = d.scenes.map(s => {
  const landed = names.indexOf(s.file_name) !== -1;
  return '  ' + s.timing_start + ' - ' + s.timing_end + '  ' + s.file_name + (landed ? '' : '  [MISSING]');
}).join('\n');

const refBlock = sep + '\n' + REF_TAG + '\nTriggered: ' + triggered + '\nUpdated: ' + stamp + '\nRun time: ' + runtime + '\nClips: ' + d.clips_found + ' of ' + d.clips_expected + '\nDrive folder: ' + d.folder_link + '\nManus Task URL: ' + d.manus_task_url + '\nTimestamps are the edit-timeline position each clip drops into, computed from the script at 150 wpm by WF06c.\n\n' + rows;
const refBase = freshRef.replace(blockRe(REF_TAG), '').trim();
const refFinal = (refBase ? refBase + '\n\n' : '') + refBlock;

const notesBlock = sep + '\n' + NOTES_TAG + '\nTriggered: ' + triggered + '\nUpdated: ' + stamp + '\nRun time: ' + runtime + '\nStage: Complete' + '\nClips: ' + d.clips_found + ' of ' + d.clips_expected + '\nDrive folder: ' + d.folder_link + '\nManus Task ID: ' + d.manus_task_id + '\nManus Task URL: ' + d.manus_task_url + '\n\nEdit timeline (insert each clip at):\n' + timeline;
const notesBase = refetchOk ? freshNotes.replace(blockRe(NOTES_TAG), '').trim() : (d.notes_base || '');
const notesFinal = (notesBase ? notesBase + '\n\n' : '') + notesBlock;

// MC-1: only the run that owns the record may write its final status.
const stillOurs = !refetchOk || ((f.BRoll_URL || '') === d.folder_link && f.Status === 'B-Roll Processing');
const lateMinutes = (d.max_poll_attempts || 24) * 5;
const lateBlock = sep + '\n' + NOTES_TAG + '\nTriggered: ' + triggered + '\nUpdated: ' + stamp + '\nRun time: ' + runtime + '\nStage: Late - Manus had not uploaded the clips after ' + lateMinutes + ' minutes' + '\nClips: ' + d.clips_found + ' of ' + d.clips_expected + '\nDrive folder: ' + d.folder_link + '\nManus Task ID: ' + d.manus_task_id + '\nManus Task URL: ' + d.manus_task_url + '\nDetail: The Manus task may still finish. Once the clips are in the folder, set status to Ready for B-roll Generation - the workflow picks them up from this folder without a new Manus task.';
const lateNotes = (notesBase ? notesBase + '\n\n' : '') + lateBlock;

return { json: { ...d, scene_map_final: refFinal, reel_notes_final: notesFinal, late_notes_final: lateNotes, still_ours: stillOurs, is_late: d.poll_timed_out === true } };

const OUTPUT_TYPE = 'broll';

function parseJson(raw, label) {
  if (!raw) return {};
  try {
    const v = JSON.parse(raw);
    if (v && typeof v === 'object' && !Array.isArray(v)) return v;
    return {};
  } catch (e) { console.log('[0b] Invalid Config_JSON on ' + label + ': ' + e.message); return {}; }
}

const outputs = $input.all().map(i => i.json);
const clients = $('0a. Load Clients').all().map(i => i.json);
const outByKey = {};
for (const o of outputs) {
  const key = (o['Key'] || '').trim().toLowerCase();
  if (key) outByKey[key] = o;
}

const out = [];
for (const c of clients) {
  const name = c['Client_Name'];
  if (!name) continue;
  if (c['Video_Enabled'] !== true) continue;
  if (!c['Video_Base_ID']) continue;
  const o = outByKey[(name + '::' + OUTPUT_TYPE).toLowerCase()] || null;
  const merged = { ...parseJson(c['Config_JSON'], name), ...parseJson(o ? o['Config_JSON'] : '', name + '::' + OUTPUT_TYPE) };
  const capRaw = parseInt(c['Daily_BRoll_Cap'], 10);
  out.push({ json: {
    ...merged,
    client_name: name,
    video_base_id: c['Video_Base_ID'],
    brand_name: c['Brand_Name'] || name,
    timezone: c['Timezone'] || 'Asia/Manila',
    output_type: OUTPUT_TYPE,
    daily_broll_cap: capRaw > 0 ? capRaw : 3,
    drive_shared_drive_id: c['Drive_Shared_Drive_ID'] || '',
    drive_folder_id: o ? (o['Drive_Folder_ID'] || '') : '',
    manus_project_id: o ? (o['Manus_Project_ID'] || '') : '',
    skill_name: o ? (o['Skill_Name'] || '') : '',
    skill_fallback: o ? (o['Skill_Fallback'] || '') : ''
  } });
}
console.log('[0b] Clients to process: ' + out.length);
return out;

const loop = $('0c. Client Loop');
let cfg = null;
try { cfg = loop.item.json; } catch (e) { cfg = null; }
if (!cfg || !cfg.video_base_id) { throw new Error('Could not resolve client config for this iteration.'); }
return { json: { ...$input.item.json, cfg, started_at: new Date().toISOString() } };

// Scenes come straight from the production brief WF06c already wrote.
// No second segmentation pass, no LLM call. Narrative role and visual style are
// deliberately NOT set here - the Manus skill owns that vocabulary.
// T-51: every scene is a distinct cut by default. chain_from_previous is true only
// when the brief marks the scene as a continuous shot of the previous one.
const d = $input.item.json;
const cfg = d.cfg || {};
const b = cfg.broll || {};

const DEFAULT_DUR = b.default_duration_seconds || 8;
const CONTINUOUS_RE = /\b(continuous (shot|take)|continues (from )?the previous (shot|scene|clip)|continuation of the previous (shot|scene|clip)|same shot continued)\b/i;

const toSec = (mmss) => {
  const m = String(mmss).match(/(\d+):(\d{1,2})/);
  if (!m) return null;
  return parseInt(m[1], 10) * 60 + parseInt(m[2], 10);
};
const toMmss = (sec) => {
  const s = Math.max(0, Math.round(sec));
  return Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0');
};

// WF06c writes numbered lines like: "1. description at 0:05-0:12 \u2014 reason"
const parseList = (raw) => {
  const items = [];
  let cur = null;
  for (const line of String(raw || '').split('\n')) {
    const t = line.trim();
    if (!t) continue;
    const m = t.match(/^(\d+)\.\s+(.*)$/);
    if (m) {
      if (cur) items.push(cur);
      cur = { n: parseInt(m[1], 10), text: m[2] };
    } else if (cur) {
      cur.text += ' ' + t;
    }
  }
  if (cur) items.push(cur);

  return items.map(x => {
    let text = x.text;
    let cue = '';
    let cueEnd = '';
    let note = '';
    const dash = text.split('\u2014');
    if (dash.length > 1) {
      note = dash.slice(1).join('\u2014').trim();
      text = dash[0].trim();
    }
    const rng = text.match(/\s+at\s+(\d+:\d{1,2})\s*-\s*(\d+:\d{1,2})\s*$/);
    const single = text.match(/\s+at\s+(\d+:\d{1,2})\s*$/);
    if (rng) { cue = rng[1]; cueEnd = rng[2]; text = text.slice(0, rng.index).trim(); }
    else if (single) { cue = single[1]; text = text.slice(0, single.index).trim(); }
    return { n: x.n, description: text, cue: cue, cue_end: cueEnd, note: note };
  });
};

const gen = parseList(d.broll_generated);
const ref = parseList(d.broll_reference);

const slugOf = (s) => (String(s).toLowerCase().replace(/[^a-z0-9\s-]/g, '').trim().split(/\s+/).slice(0, 4).join('-').substring(0, 40) || 'scene');

const scenes = [];
for (let i = 0; i < gen.length; i++) {
  const g = gen[i];
  const r = ref[i] || {};
  const startSec = toSec(g.cue);
  let endSec = toSec(g.cue_end);
  if (startSec !== null && (endSec === null || endSec <= startSec)) { endSec = startSec + DEFAULT_DUR; }
  const dur = (startSec !== null && endSec !== null) ? (endSec - startSec) : DEFAULT_DUR;
  const id = 'scene_' + (i + 1);
  const slug = slugOf(g.description);
  scenes.push({
    id: id,
    file_slug: slug,
    file_name: id + '_' + slug + '.mp4',
    scene_direction: g.description + (g.note ? ' ' + g.note : ''),
    style_reference: r.description || '',
    timing_start: startSec !== null ? toMmss(startSec) : '',
    timing_end: endSec !== null ? toMmss(endSec) : '',
    duration_seconds: Math.max(1, Math.round(dur)),
